// ===== 日志系统 =====
function getLogKey() { return 'OS_ACTIVITY_LOG'; }
function getLogs() {
    try { return JSON.parse(memGetItem(getLogKey()) || '[]'); }
    catch(e) { return []; }
}
function saveLogs(logs) { memSetItem(getLogKey(), JSON.stringify(logs)); }
function clearLogs() { memRemoveItem(getLogKey()); }

function addLog(action) {
    if (!OS_DATA.settings.logEnabled) return;
    const now = new Date();
    const pad = n => String(n).padStart(2, '0');
    const ts = now.getFullYear() + '-' + pad(now.getMonth()+1) + '-' + pad(now.getDate()) + ' ' +
               pad(now.getHours()) + ':' + pad(now.getMinutes()) + ':' + pad(now.getSeconds());
    const logs = getLogs();
    logs.push(ts + ' ' + action);
    if (logs.length > 5000) logs.splice(0, logs.length - 5000);
    saveLogs(logs);
}

function downloadLogFile() {
    const logs = getLogs();
    const text = logs.join('\n');
    const blob = new Blob([text], { type: 'text/plain;charset=utf-8' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    const pad = n => String(n).padStart(2, '0');
    const now = new Date();
    link.download = 'WebOS_Log_' + now.getFullYear() + pad(now.getMonth()+1) + pad(now.getDate()) + '_' +
                    pad(now.getHours()) + pad(now.getMinutes()) + pad(now.getSeconds()) + '.txt';
    link.style.cssText = 'position:fixed;top:0;left:0;z-index:2147483647;opacity:0;pointer-events:auto;';
    document.documentElement.appendChild(link);
    link.click();
    setTimeout(function() {
        document.documentElement.removeChild(link);
        URL.revokeObjectURL(link.href);
    }, 3000);
}

