let _draggingFileId = null;  // 全局拖拽通信变量，用于跨组件拖放
let _inputLogTimer = {};
function logInputDebounced(inputId, fileName, value) {
    if (!OS_DATA.settings.logEnabled) return;
    clearTimeout(_inputLogTimer[inputId]);
    _inputLogTimer[inputId] = setTimeout(function() {
        const preview = value.length > 30 ? value.substring(0, 30) + '...' : value;
        addLog('在文件「' + fileName + '」中输入了：' + preview);
    }, 2000);
}

    let zIndexCounter = 200000;
    function renderMarkdown(text) {
        // ===== 第一步：自动为公式行添加 $ 包裹 =====
        function autoWrapLatex(str) {
            // 常见 LaTeX 命令（可根据需要扩充）
            const latexKeywords = [
                '\\frac', '\\pi', '\\sum', '\\int', '\\alpha', '\\beta', '\\gamma',
                '\\delta', '\\epsilon', '\\theta', '\\lambda', '\\mu', '\\omega',
                '\\rightarrow', '\\leftarrow', '\\sqrt', '\\infty', '\\le', '\\ge',
                '\\neq', '\\approx', '\\times', '\\div', '\\pm', '\\cdot', '\\ldots',
                '\\partial', '\\nabla', '\\prod', '\\iint', '\\iiint', '\\oint',
                '\\angle', '\\degree', '\\prime', '\\hbar', '\\ell'
            ];
            // 构建正则：匹配这些命令（前面加 \b 避免部分匹配）
            const pattern = new RegExp('\\b(' + latexKeywords.join('|') + ')\\b', 'i');
            const lines = str.split('\n');
            for (let i = 0; i < lines.length; i++) {
                const line = lines[i];
                if (!line.trim()) continue;
                // 如果行内已经有 $ 或 $$，跳过（避免破坏已有格式）
                if (line.includes('$') || line.includes('$$')) continue;
                // 如果行内包含 LaTeX 命令或明显的数学符号（=、+、-、*、/、^、_ 等且含数字）
                // 简单判断：包含 LaTeX 命令 或（包含数学运算符且包含数字）
                const hasLatexCmd = pattern.test(line);
                const hasMathOps = /[=+\-*/^_]/.test(line) && /\d/.test(line);
                if (hasLatexCmd || hasMathOps) {
                    // 将整行包裹为行内公式 $...$
                    lines[i] = '$' + line + '$';
                }
            }
            return lines.join('\n');
        }

        // 先执行自动包裹
        text = autoWrapLatex(text);

        // ===== 第二步：用 marked 解析 Markdown =====
        if (typeof marked !== 'undefined') {
            try {
                let html = marked.parse(text);
                // ===== 第三步：渲染 LaTeX（$...$ 和 $$...$$） =====
                html = renderLatexInHtml(html);
                return html;
            } catch (e) {
                // 如果 marked 解析失败，降级到备用渲染器
            }
        }

        // ===== 备用渲染器（marked 不可用时） =====
        let html = escapeHTML(text);

        // 处理 LaTeX（同样的方法）
        html = renderLatexInHtml(html);

        // 代码块（```...```）
        html = html.replace(/```(\w*)\n([\s\S]*?)```/g, (m, lang, code) => {
            return `<pre style="background:rgba(0,0,0,0.3);padding:12px;border-radius:6px;overflow-x:auto;margin:8px 0;border:1px solid rgba(255,255,255,0.1);"><code>${code.trim()}</code></pre>`;
        });

        // 行内代码（`...`）
        html = html.replace(/`([^`]+)`/g, '<code style="background:rgba(0,0,0,0.3);padding:2px 6px;border-radius:3px;font-family:Consolas,monospace;font-size:0.9em;">$1</code>');

        // 粗体和斜体
        html = html.replace(/\*\*(.+?)\*\*/g, '<b>$1</b>');
        html = html.replace(/\*(.+?)\*/g, '<i>$1</i>');

        // 换行
        html = html.replace(/\n/g, '<br>');

        return html;
    }

    // ===== LaTeX 公式渲染核心函数 =====
    function renderLatexInHtml(html) {
        // 处理块级公式 $$ ... $$（先处理块级，避免被行内干扰）
        html = html.replace(/\$\$([\s\S]*?)\$\$/g, (match, latex) => {
            const trimmed = latex.trim();
            // 尝试渲染，失败则显示原始文本
            return renderLatexBlock(trimmed, true);
        });

        // 处理行内公式 $ ... $（注意避免匹配到 $$ 块级）
        html = html.replace(/\$(?!\$)([^\$\n]*?)\$(?!\$)/g, (match, latex) => {
            const trimmed = latex.trim();
            return renderLatexBlock(trimmed, false);
        });

        // 处理 \( ... \) 格式的行内公式（LaTeX 标准语法）
        html = html.replace(/\\\(([\s\S]*?)\\\)/g, (match, latex) => {
            const trimmed = latex.trim();
            return renderLatexBlock(trimmed, false);
        });

        // 处理 \[ ... \] 格式的块级公式（LaTeX 标准语法）
        html = html.replace(/\\\[([\s\S]*?)\\\]/g, (match, latex) => {
            const trimmed = latex.trim();
            return renderLatexBlock(trimmed, true);
        });

        return html;
    }
// ===== 渲染单个 LaTeX 表达式（增强版，支持简写分数） =====
function renderLatexBlock(latex, isBlock) {
    try {
        let processed = latex;

        // 1. 处理 \left 和 \right
        processed = processed.replace(/\\left\s*([\(\[\{\|\|])/g, function(m, p1) {
            return { '(': '(', '[': '[', '{': '{', '|': '|', '||': '||' }[p1] || p1;
        });
        processed = processed.replace(/\\right\s*([\)\]\}\|\|])/g, function(m, p1) {
            return { ')': ')', ']': ']', '}': '}', '|': '|', '||': '||' }[p1] || p1;
        });

        // 2. 常用 LaTeX 命令转 Unicode（希腊字母、运算符等）
        const symbolMap = {
            // 希腊字母
            '\\alpha': 'α', '\\beta': 'β', '\\gamma': 'γ', '\\delta': 'δ',
            '\\epsilon': 'ε', '\\zeta': 'ζ', '\\eta': 'η', '\\theta': 'θ',
            '\\iota': 'ι', '\\kappa': 'κ', '\\lambda': 'λ', '\\mu': 'μ',
            '\\nu': 'ν', '\\xi': 'ξ', '\\pi': 'π', '\\rho': 'ρ',
            '\\sigma': 'σ', '\\tau': 'τ', '\\upsilon': 'υ', '\\phi': 'φ',
            '\\chi': 'χ', '\\psi': 'ψ', '\\omega': 'ω',
            '\\Gamma': 'Γ', '\\Delta': 'Δ', '\\Theta': 'Θ', '\\Lambda': 'Λ',
            '\\Xi': 'Ξ', '\\Pi': 'Π', '\\Sigma': 'Σ', '\\Phi': 'Φ',
            '\\Psi': 'Ψ', '\\Omega': 'Ω',
            // 关系运算符
            '\\le': '≤', '\\ge': '≥', '\\ll': '≪', '\\gg': '≫',
            '\\neq': '≠', '\\equiv': '≡', '\\approx': '≈', '\\sim': '∼',
            '\\propto': '∝',
            // 箭头
            '\\rightarrow': '→', '\\Rightarrow': '⇒', '\\longrightarrow': '⟶',
            '\\leftarrow': '←', '\\Leftarrow': '⇐', '\\longleftarrow': '⟵',
            '\\leftrightarrow': '↔', '\\Leftrightarrow': '⇔',
            // 运算符
            '\\times': '×', '\\div': '÷', '\\pm': '±', '\\mp': '∓',
            '\\cdot': '·', '\\ast': '∗', '\\star': '⋆', '\\circ': '∘',
            '\\bullet': '•',
            // 集合
            '\\in': '∈', '\\notin': '∉', '\\subset': '⊂', '\\supset': '⊃',
            '\\subseteq': '⊆', '\\supseteq': '⊇', '\\cup': '∪', '\\cap': '∩',
            '\\emptyset': '∅', '\\infty': '∞', '\\forall': '∀', '\\exists': '∃',
            '\\nexists': '∄',
            // 逻辑
            '\\land': '∧', '\\lor': '∨', '\\lnot': '¬', '\\top': '⊤', '\\bot': '⊥',
            // 其他
            '\\partial': '∂', '\\nabla': '∇', '\\sqrt': '√',
            '\\sum': '∑', '\\prod': '∏', '\\int': '∫',
            '\\iint': '∬', '\\iiint': '∭', '\\oint': '∮',
            '\\angle': '∠', '\\degree': '°', '\\prime': '′',
            '\\hbar': 'ħ', '\\ell': 'ℓ'
        };
        for (const [cmd, char] of Object.entries(symbolMap)) {
            processed = processed.replace(new RegExp(cmd.replace(/\\/g, '\\\\'), 'g'), char);
        }

        // 3. 处理分数 \frac（支持三种写法）
        function replaceFrac(str) {
            let prev;
            do {
                prev = str;
                // 3a. 标准形式 \frac{...}{...}
                str = str.replace(/\\frac\{([^{}]*(?:\{[^{}]*\}[^{}]*)*)\}\{([^{}]*(?:\{[^{}]*\}[^{}]*)*)\}/g, function(m, num, den) {
                    return `<span style="display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;margin:0 2px;font-size:0.9em;line-height:1.2;">
                                <span style="border-bottom:1px solid currentColor;padding:0 6px;">${num}</span>
                                <span style="padding:0 6px;">${den}</span>
                            </span>`;
                });
                // 3b. \frac{...}X 分母为单个字符（数字或字母）
                str = str.replace(/\\frac\{([^{}]*(?:\{[^{}]*\}[^{}]*)*)\}([a-zA-Z0-9])/g, function(m, num, den) {
                    return `<span style="display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;margin:0 2px;font-size:0.9em;line-height:1.2;">
                                <span style="border-bottom:1px solid currentColor;padding:0 6px;">${num}</span>
                                <span style="padding:0 6px;">${den}</span>
                            </span>`;
                });
                // 3c. \frac ab 分子和分母都是单个字符
                str = str.replace(/\\frac([a-zA-Z0-9])([a-zA-Z0-9])/g, function(m, num, den) {
                    return `<span style="display:inline-flex;flex-direction:column;align-items:center;vertical-align:middle;margin:0 2px;font-size:0.9em;line-height:1.2;">
                                <span style="border-bottom:1px solid currentColor;padding:0 6px;">${num}</span>
                                <span style="padding:0 6px;">${den}</span>
                            </span>`;
                });
            } while (prev !== str);
            return str;
        }
        processed = replaceFrac(processed);

        // 4. 处理上下标
        processed = processed.replace(/_\{([^}]*)\}/g, '<sub>$1</sub>');
        processed = processed.replace(/\^\{([^}]*)\}/g, '<sup>$1</sup>');
        processed = processed.replace(/_([a-zA-Z0-9])/g, '<sub>$1</sub>');
        processed = processed.replace(/\^([a-zA-Z0-9])/g, '<sup>$1</sup>');

        // 5. 构建显示样式
        const displayStyle = isBlock
            ? 'display:block;text-align:center;padding:8px 12px;margin:6px 0;background:rgba(0,0,0,0.15);border-radius:6px;font-size:1.15em;'
            : 'display:inline;font-style:italic;padding:0 2px;';

        return `<span style="${displayStyle}font-family:'Times New Roman',serif;letter-spacing:0.5px;">${processed}</span>`;

    } catch (e) {
        return `<span style="color:#ff6b6b;font-family:monospace;">[LaTeX: ${escapeHTML(latex)}]</span>`;
    }
}

    // 保留原有的 escapeHTML 函数
    function escapeHTML(str) {
        if (!str) return '';
        return str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    }
