    // ============================================================
    // 【修复】未匹配括号检测 — 使用独立栈
    // 旧算法：单个栈，遇到闭合括号时从栈顶往下找匹配的开括号，
    //         把中间所有不匹配的开括号都标记为未匹配 → 错误！
    //         例如 "({)}" → 遇到 ) 时，栈=[{, (]，从栈顶找到 ( 配对，
    //         但中间的 { 也被标记为未匹配 → 错！实际上 { 和 } 是配对的！
    //
    // 新算法：每种括号类型各维护一个独立栈
    //         遇到 ) 只看 ( 栈，遇到 ] 只看 [ 栈，遇到 } 只看 { 栈
    //         这样不同类型的括号互不干扰
    // ============================================================
    function findUnmatchedBrackets(text) {
        const result = new Uint8Array(text.length);

        // 每种括号类型独立栈
        const stacks = {
            '(': [],  // round brackets
            '[': [],  // square brackets
            '{': []   // curly brackets
        };
        const matchMap = { ')': '(', ']': '[', '}': '{' };

        // 先扫描标记字符串和注释，跳过它们
        const inString = new Uint8Array(text.length);
        const inComment = new Uint8Array(text.length);

        for (let i = 0; i < text.length; i++) {
            const ch = text[i];
            // 检测字符串
            if (ch === '"' || ch === "'") {
                const quote = ch;
                inString[i] = 1;
                i++;
                while (i < text.length) {
                    if (text[i] === '\\') { inString[i] = 1; i++; if (i < text.length) inString[i] = 1; i++; continue; }
                    if (text[i] === quote) { inString[i] = 1; break; }
                    inString[i] = 1;
                    i++;
                }
                continue;
            }
            // 检测单行注释
            if (ch === '/' && i + 1 < text.length && text[i + 1] === '/') {
                while (i < text.length && text[i] !== '\n') { inComment[i] = 1; i++; }
                i--;
                continue;
            }
            // 检测多行注释
            if (ch === '/' && i + 1 < text.length && text[i + 1] === '*') {
                inComment[i] = 1; i++; inComment[i] = 1; i++;
                while (i < text.length) {
                    if (text[i] === '*' && i + 1 < text.length && text[i + 1] === '/') {
                        inComment[i] = 1; i++; inComment[i] = 1; break;
                    }
                    inComment[i] = 1; i++;
                }
                continue;
            }
        }

        // 实际括号匹配
        for (let i = 0; i < text.length; i++) {
            if (inString[i] || inComment[i]) continue;
            const ch = text[i];

            if (ch === '(' || ch === '[' || ch === '{') {
                stacks[ch].push(i);
            }
            else if (ch === ')' || ch === ']' || ch === '}') {
                const openChar = matchMap[ch];
                const stack = stacks[openChar];
                if (stack.length > 0) {
                    stack.pop(); // 匹配成功，弹出
                } else {
                    result[i] = 1; // 没有匹配的开括号，标记为未匹配
                }
            }
        }

        // 栈中剩余的都是未匹配的开括号
        for (const key in stacks) {
            for (const idx of stacks[key]) {
                result[idx] = 1;
            }
        }

        return result;
    }


// ===== 自定义语法高亮系统 (v5.9) =====
// 规则：
// 1. 同样的词一样的颜色（基于 token 类型的一致性）
// 2. [] / {} / "" 各自有不同的颜色
// 3. 不使用红色/蓝色


const SYNTAX_COLORS = {
    // 关键字 - 青柠绿
    keyword:      '#a6e22e',  // include, int, return, if, else, for, while, etc.
    // 类型 - 薄荷绿（替代原来的青色，避免蓝色）
    type:         '#4ec9b0',  // int, char, float, double, void, bool, string, etc.
    // 函数/方法 - 金黄色
    function:     '#e6db74',  // 函数名、方法调用
    // 数字 - 橙色
    number:       '#fd971f',  // 0-9, 0x, 浮点数
    // 字符串 - 暖粉色（双引号内容）- 偏品红而非红
    string:       '#ff79c6',  // "..." 内容
    // 字符 - 暖粉色（单引号内容）
    char:         '#ff79c6',  // '...' 内容
    // 注释 - 灰色
    comment:      '#75715e',  // // 和 /* */
    // 预处理器 - 紫色
    preprocessor: '#bd93f9',  // #include, #define, #ifdef, etc.
    // 运算符 - 白色
    operator:     '#f8f8f2',  // + - * / = == != < > && ||
    // 标点 - 白色
    punctuation:  '#f8f8f2',  // ; , . ::
    // 方括号 [] - 翠绿色（特殊要求：不同于 {} 和 ""）
    bracket_sq:   '#2ecc71',  // [ ]
    // 花括号 {} - 琥珀色（特殊要求：不同于 [] 和 ""）
    bracket_cl:   '#f39c12',  // { }
    // 圆括号 () - 白色
    bracket_rd:   '#f8f8f2',  // ( )
    // 标识符（变量名等）- 白色
    identifier:   '#f8f8f2',
    // 未匹配括号 - 亮橙色（错误提示，不用红色）
    unmatched:    '#ff9f43',
};

