const wallpaperInput = win.querySelector('#set-wallpaper');
wallpaperInput.onchange = function(e) {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = function(ev) {
        OS_DATA.settings.wallpaperData = ev.target.result;
        saveSystemDataNow();
        applyWallpaper();
    };
    reader.readAsDataURL(file);
};

