const bootCooldownInput = win.querySelector('#set-boot-cooldown');
bootCooldownInput.addEventListener('change', () => { var val = parseInt(bootCooldownInput.value) || 0; if (val < 0) val = 0; OS_DATA.settings.bootCooldownSeconds = val; saveSystemDataNow(); });
