                var importedData = JSON.parse(ev.target.result);
                var count = 0;

                // 遍历导入的数据，写入内存和 IndexedDB
                for (var key in importedData) {
                    if (importedData.hasOwnProperty(key) && (key.startsWith('OS_') || key.startsWith('MOCK_OS_'))) {
                        // 使用 memSetItem 写入（同时更新内存缓存和 IndexedDB）
                        memSetItem(key, importedData[key]);
                        count++;
                    }
                }

                alert('✅ 导入成功！共恢复 ' + count + ' 项数据。\n页面即将刷新以应用所有更改。');
                // 刷新页面，让所有界面重新加载新数据
